import re
from datetime import datetime


def extract(text: str) -> dict:
    if not isinstance(text, str):
        raise ValueError('text must be a string')

    provider_match = re.search(r'^From:\s*Alpha\s+Traders\b', text, re.IGNORECASE | re.MULTILINE)
    if not provider_match:
        raise ValueError('Missing From label for Alpha Traders')

    subject_match = re.search(r'^Subject:\s*(.+)$', text, re.IGNORECASE | re.MULTILINE)
    if not subject_match:
        raise ValueError('Missing Subject label')
    subject = subject_match.group(1).strip()

    amount_match = re.search(r'^Order\s+value:\s*Rs\s*([0-9][0-9,]*(?:\.\d+)?)\s*$', text, re.IGNORECASE | re.MULTILINE)
    if not amount_match:
        raise ValueError('Missing Order value label')
    amount_str = amount_match.group(1).replace(',', '')
    amount = float(amount_str)

    due_match = re.search(r'^Required\s+dispatch\s+date:\s*([0-9]{1,2}\s+[A-Za-z]{3,9}\s+[0-9]{4})\s*$', text, re.IGNORECASE | re.MULTILINE)
    if not due_match:
        raise ValueError('Missing Required dispatch date label')
    due_raw = due_match.group(1).strip()
    try:
        due_date = datetime.strptime(due_raw, '%d %b %Y').strftime('%Y-%m-%d')
    except ValueError:
        try:
            due_date = datetime.strptime(due_raw, '%d %B %Y').strftime('%Y-%m-%d')
        except ValueError:
            raise ValueError('Unparseable Required dispatch date')

    body_start = re.search(r'\n\s*\n', text)
    if not body_start:
        raise ValueError('Missing message body')
    body = text[body_start.end():].strip()
    if not body:
        raise ValueError('Empty message body')

    lower_body = body.lower()
    lower_subject = subject.lower()
    if 'expedite' in lower_body:
        topic = 'expedite shipment'
    elif 'shipment request' in lower_subject:
        topic = 'shipment request'
    else:
        topic = 'New shipment request'

    return {
        'type': 'other',
        'provider': 'Alpha Traders',
        'amount': amount,
        'currency': 'INR',
        'due_date': due_date,
        'topic': topic,
        'category': 'shipment_request',
    }
